create table if not exists public.workspace_profiles (workspace_id uuid primary key references public.workspaces(id) on delete cascade, sector text, industry text, operating_model text default 'digital_workforce', onboarding_stage text not null default 'ready', settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.task_delegations (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, parent_task_id uuid not null references public.tasks(id) on delete cascade, child_task_id uuid not null references public.tasks(id) on delete cascade, from_employee_id uuid references public.ai_employees(id) on delete set null, to_employee_id uuid references public.ai_employees(id) on delete set null, reason text not null, status text not null default 'pending' check(status in ('pending','accepted','completed','failed','cancelled')), context jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), completed_at timestamptz, unique(parent_task_id,child_task_id));
create table if not exists public.integration_action_logs (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, task_id uuid references public.tasks(id) on delete set null, employee_id uuid references public.ai_employees(id) on delete set null, connection_id uuid references public.integration_connections(id) on delete set null, provider text not null, action text not null, status text not null default 'started' check(status in ('started','succeeded','failed','blocked')), request_meta jsonb not null default '{}'::jsonb, response_meta jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), completed_at timestamptz);
create index if not exists task_delegations_workspace_idx on public.task_delegations(workspace_id,created_at desc);
create index if not exists integration_action_logs_workspace_idx on public.integration_action_logs(workspace_id,created_at desc);
alter table public.tasks add column if not exists parent_task_id uuid references public.tasks(id) on delete set null;
alter table public.tasks add column if not exists assigned_by_employee_id uuid references public.ai_employees(id) on delete set null;
create index if not exists tasks_parent_idx on public.tasks(workspace_id,parent_task_id);
create or replace view public.workspace_command_center as select w.id as workspace_id,(select count(*) from public.ai_employees e where e.workspace_id=w.id and e.status='active')::int as active_employees,(select count(*) from public.tasks t where t.workspace_id=w.id and t.status in ('queued','planning','executing','awaiting_approval'))::int as open_tasks,(select count(*) from public.tasks t where t.workspace_id=w.id and t.status='completed')::int as completed_tasks,(select count(*) from public.tasks t where t.workspace_id=w.id and t.status='failed')::int as failed_tasks,(select count(*) from public.approvals a where a.workspace_id=w.id and a.status='pending')::int as pending_approvals,(select count(*) from public.integration_connections i where i.workspace_id=w.id and i.status='active')::int as active_integrations,(select count(*) from public.employee_handoffs h where h.workspace_id=w.id and h.status in ('pending','accepted'))::int as active_handoffs,(select coalesce(sum(r.cost_cents),0)::bigint from public.runtime_metrics r where r.workspace_id=w.id) as runtime_cost_cents,(select max(r.created_at) from public.runtime_metrics r where r.workspace_id=w.id) as last_runtime_at from public.workspaces w;
alter view public.workspace_command_center set (security_invoker=true);
alter table public.workspace_profiles enable row level security;
alter table public.task_delegations enable row level security;
alter table public.integration_action_logs enable row level security;
create policy workspace_profiles_member_select on public.workspace_profiles for select using (public.is_workspace_member(workspace_id));
create policy task_delegations_member_select on public.task_delegations for select using (public.is_workspace_member(workspace_id));
create policy integration_action_logs_member_select on public.integration_action_logs for select using (public.is_workspace_member(workspace_id));
